// PWA registration + install prompt plumbing.
//
// The service worker is generated by vite-plugin-pwa (registerType 'prompt'):
// a new SW activation surfaces "Update available — Reload" in the UI instead
// of silently reloading. This module is a tiny pub/sub so React components
// can subscribe without importing the virtual module directly.

import { registerSW } from 'virtual:pwa-register';

export interface PwaState {
  updateAvailable: boolean;
  offlineReady: boolean;
  canInstall: boolean;
  installed: boolean;
}

type Listener = () => void;

let state: PwaState = {
  updateAvailable: false,
  offlineReady: false,
  canInstall: false,
  installed: false,
};

const listeners = new Set<Listener>();
let applyUpdateFn: (() => Promise<void>) | null = null;
let deferredPrompt: BeforeInstallPromptEvent | null = null;

export interface BeforeInstallPromptEvent extends Event {
  prompt(): Promise<void>;
  userChoice: Promise<{ outcome: 'accepted' | 'dismissed' }>;
}

function notify(): void {
  for (const l of listeners) l();
}

function set(patch: Partial<PwaState>): void {
  state = { ...state, ...patch };
  notify();
}

export function getPwaState(): PwaState {
  return state;
}

export function subscribePwa(listener: Listener): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

export function applyUpdate(): void {
  void applyUpdateFn?.();
}

export async function promptInstall(): Promise<void> {
  if (!deferredPrompt) return;
  await deferredPrompt.prompt();
  const choice = await deferredPrompt.userChoice;
  deferredPrompt = null;
  if (choice.outcome === 'accepted') set({ canInstall: false, installed: true });
}

export function initPwa(): void {
  state.installed =
    globalThis.matchMedia?.('(display-mode: standalone)').matches ||
    (globalThis.navigator as { standalone?: boolean }).standalone === true;

  window.addEventListener('beforeinstallprompt', (event) => {
    event.preventDefault();
    deferredPrompt = event as BeforeInstallPromptEvent;
    if (!state.installed) set({ canInstall: true });
  });

  window.addEventListener('appinstalled', () => {
    set({ canInstall: false, installed: true });
  });

  if ('serviceWorker' in navigator) {
    applyUpdateFn = registerSW({
      onNeedRefresh() {
        set({ updateAvailable: true });
      },
      onOfflineReady() {
        set({ offlineReady: true });
      },
    });
  }
}
